using System.Security.Claims;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Pages;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Components;
using ShipmentTracker.Components.Account;
using ShipmentTracker.Data;
using ShipmentTracker.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents()
    .AddInteractiveWebAssemblyComponents()
    .AddAuthenticationStateSerialization(options => options.SerializeAllClaims = true);

builder.Services.AddCascadingAuthenticationState();
builder.Services.AddScoped<IdentityRedirectManager>();
builder.Services.AddScoped<AuthenticationStateProvider, IdentityRevalidatingAuthenticationStateProvider>();

builder.Services.AddAuthentication(options =>
    {
        options.DefaultScheme = IdentityConstants.ApplicationScheme;
        options.DefaultSignInScheme = IdentityConstants.ExternalScheme;
    })
    .AddIdentityCookies();

var connectionString = builder.Configuration.GetConnectionString("DefaultConnection") ?? throw new InvalidOperationException("Connection string 'DefaultConnection' not found.");
builder.Services.AddDbContext<ApplicationDbContext>(options =>
    options.UseSqlite(connectionString));
builder.Services.AddDatabaseDeveloperPageExceptionFilter();

builder.Services.AddIdentityCore<ApplicationUser>(options =>
    {
        options.SignIn.RequireConfirmedAccount = true;
        options.Stores.SchemaVersion = IdentitySchemaVersions.Version3;
    })
    .AddRoles<IdentityRole>()
    .AddEntityFrameworkStores<ApplicationDbContext>()
    .AddSignInManager()
    .AddDefaultTokenProviders();

builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();
builder.Services.AddScoped<IShipmentService, ServerShipmentService>();

var app = builder.Build();

// Apply migrations and seed data on startup
using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    await db.Database.MigrateAsync();

    if (!db.Shipments.Any())
    {
        db.Shipments.AddRange(
            new Shipment { TrackingNumber = "TRK-20260601-001", Origin = "New York, USA", Destination = "London, UK", Status = (int)ShipmentStatus.InTransit, CreatedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(4), CustomerEmail = "customer@example.com", Description = "Electronics - Laptop", WeightKg = 3.2 },
            new Shipment { TrackingNumber = "TRK-20260601-002", Origin = "Shanghai, China", Destination = "Los Angeles, USA", Status = (int)ShipmentStatus.PickedUp, CreatedDate = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(12), CustomerEmail = "customer@example.com", Description = "Furniture - Office Chair", WeightKg = 18.5 },
            new Shipment { TrackingNumber = "TRK-20260601-003", Origin = "Berlin, Germany", Destination = "Tokyo, Japan", Status = (int)ShipmentStatus.Pending, CreatedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(10), CustomerEmail = "another@example.com", Description = "Auto Parts", WeightKg = 7.0 },
            new Shipment { TrackingNumber = "TRK-20260601-004", Origin = "São Paulo, Brazil", Destination = "Sydney, Australia", Status = (int)ShipmentStatus.Delivered, CreatedDate = DateTime.UtcNow.AddDays(-14), EstimatedDelivery = DateTime.UtcNow.AddDays(-2), CustomerEmail = "another@example.com", Description = "Textiles", WeightKg = 12.0 },
            new Shipment { TrackingNumber = "TRK-20260601-005", Origin = "Dubai, UAE", Destination = "Paris, France", Status = (int)ShipmentStatus.OutForDelivery, CreatedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow, CustomerEmail = "customer@example.com", Description = "Perishable Goods", WeightKg = 5.4 }
        );
        await db.SaveChangesAsync();
    }
}

// Configure the HTTP request pipeline.
if (app.Environment.IsDevelopment())
{
    app.UseWebAssemblyDebugging();
    app.UseMigrationsEndPoint();
}
else
{
    app.UseExceptionHandler("/Error", createScopeForErrors: true);
    // The default HSTS value is 30 days. You may want to change this for production scenarios, see https://aka.ms/aspnetcore-hsts.
    app.UseHsts();
}
app.UseStatusCodePagesWithReExecute("/not-found", createScopeForStatusCodePages: true);
app.UseHttpsRedirection();

app.UseAntiforgery();

// --- Shipment API Endpoints ---
var shipmentApi = app.MapGroup("api/shipments").RequireAuthorization();

shipmentApi.MapGet("/", async (ApplicationDbContext db) =>
{
    var shipments = await db.Shipments.OrderByDescending(s => s.CreatedDate).ToListAsync();
    return Results.Ok(shipments.Select(ToDto));
}).RequireAuthorization("DispatcherPolicy");

shipmentApi.MapGet("/mine", async (ApplicationDbContext db, ClaimsPrincipal user) =>
{
    var email = user.FindFirstValue(ClaimTypes.Email);
    var shipments = await db.Shipments
        .Where(s => s.CustomerEmail == email)
        .OrderByDescending(s => s.CreatedDate)
        .ToListAsync();
    return Results.Ok(shipments.Select(ToDto));
});

shipmentApi.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
{
    var entity = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
    return entity is null ? Results.NotFound() : Results.Ok(ToDto(entity));
});

shipmentApi.MapGet("/{id:int}", async (int id, ApplicationDbContext db) =>
{
    var entity = await db.Shipments.FindAsync(id);
    return entity is null ? Results.NotFound() : Results.Ok(ToDto(entity));
});

shipmentApi.MapPost("/", async (ShipmentDto dto, ApplicationDbContext db) =>
{
    var entity = new Shipment
    {
        TrackingNumber = dto.TrackingNumber,
        Origin = dto.Origin,
        Destination = dto.Destination,
        Status = (int)dto.Status,
        CreatedDate = DateTime.UtcNow,
        EstimatedDelivery = dto.EstimatedDelivery,
        CustomerEmail = dto.CustomerEmail,
        Description = dto.Description,
        WeightKg = dto.WeightKg
    };
    db.Shipments.Add(entity);
    await db.SaveChangesAsync();
    return Results.Created($"api/shipments/{entity.Id}", ToDto(entity));
}).RequireAuthorization("DispatcherPolicy");

shipmentApi.MapPut("/{id:int}/status", async (int id, ShipmentStatus status, ApplicationDbContext db) =>
{
    var entity = await db.Shipments.FindAsync(id);
    if (entity is null) return Results.NotFound();
    entity.Status = (int)status;
    await db.SaveChangesAsync();
    return Results.NoContent();
}).RequireAuthorization("DispatcherPolicy");

app.MapStaticAssets();
app.MapRazorComponents<App>()
    .AddInteractiveServerRenderMode()
    .AddInteractiveWebAssemblyRenderMode()
    .AddAdditionalAssemblies(typeof(ShipmentTracker.Client._Imports).Assembly);

// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

app.Run();

static ShipmentDto ToDto(Shipment s) => new()
{
    Id = s.Id,
    TrackingNumber = s.TrackingNumber,
    Origin = s.Origin,
    Destination = s.Destination,
    Status = (ShipmentStatus)s.Status,
    CreatedDate = s.CreatedDate,
    EstimatedDelivery = s.EstimatedDelivery,
    CustomerEmail = s.CustomerEmail,
    Description = s.Description,
    WeightKg = s.WeightKg
};

