@page "/shipments"
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>All Shipments</PageTitle>

<h2>📋 All Shipments</h2>

<div class="row mb-3 g-2">
    <div class="col-auto">
        <input class="form-control" placeholder="Filter by destination..." @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-auto">
        <select class="form-select" @bind="filterStatus">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-auto">
        <a href="shipments/create" class="btn btn-success">➕ New Shipment</a>
    </div>
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p class="text-muted">No shipments match your filter.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Customer</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @StatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                        <td>@(s.CustomerEmail ?? "—")</td>
                        <td>
                            @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
                            {
                                <div class="btn-group btn-group-sm">
                                    <select class="form-select form-select-sm" style="width:auto"
                                            @onchange="e => UpdateStatus(s, e)">
                                        @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                        {
                                            <option value="@status" selected="@(status == s.Status)">@status</option>
                                        }
                                    </select>
                                </div>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = "";
    private string filterStatus = "";

    private IEnumerable<ShipmentDto> FilteredShipments => shipments?
        .Where(s => string.IsNullOrEmpty(filterText) || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase))
        .Where(s => string.IsNullOrEmpty(filterStatus) || s.Status.ToString() == filterStatus)
        ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus) && newStatus != shipment.Status)
        {
            await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string StatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2>🔍 Track a Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input class="form-control" placeholder="Enter tracking number (e.g. TRK-20260601-001)"
                   @bind="trackingNumber" @onkeydown="OnKeyDown" />
            <button class="btn btn-primary" @onclick="Search" disabled="@searching">
                @if (searching) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Search
            </button>
        </div>
    </div>
</div>

@if (searched && shipment is null)
{
    <div class="alert alert-warning">
        No shipment found with tracking number <strong>@searchedNumber</strong>. Please verify and try again.
    </div>
}

@if (shipment is not null)
{
    <div class="card shadow-sm">
        <div class="card-header bg-dark text-white">
            <h5 class="mb-0">Tracking: <code class="text-light">@shipment.TrackingNumber</code></h5>
        </div>
        <div class="card-body">
            <div class="row g-3">
                <div class="col-md-6">
                    <strong>Origin:</strong> @shipment.Origin
                </div>
                <div class="col-md-6">
                    <strong>Destination:</strong> @shipment.Destination
                </div>
                <div class="col-md-6">
                    <strong>Status:</strong>
                    <span class="badge @StatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
                </div>
                <div class="col-md-6">
                    <strong>Estimated Delivery:</strong>
                    @if (shipment.EstimatedDelivery.HasValue)
                    {
                        <span>@shipment.EstimatedDelivery.Value.ToString("dddd, MMM dd, yyyy")</span>
                        @if (shipment.EstimatedDelivery.Value > DateTime.UtcNow)
                        {
                            <span class="text-muted ms-1">(@((shipment.EstimatedDelivery.Value - DateTime.UtcNow).Days) days remaining)</span>
                        }
                    }
                    else
                    {
                        <span class="text-muted">Not available</span>
                    }
                </div>
                <div class="col-md-6">
                    <strong>Description:</strong> @(shipment.Description ?? "—")
                </div>
                <div class="col-md-6">
                    <strong>Weight:</strong> @(shipment.WeightKg.HasValue ? $"{shipment.WeightKg:F1} kg" : "—")
                </div>
                <div class="col-md-6">
                    <strong>Shipped On:</strong> @shipment.CreatedDate.ToString("MMM dd, yyyy")
                </div>
            </div>

            <hr />
            <h6>Delivery Progress</h6>
            <div class="progress" style="height: 30px;">
                <div class="progress-bar @ProgressBarClass(shipment.Status)"
                     role="progressbar"
                     style="width: @ProgressPercent(shipment.Status)%"
                     aria-valuenow="@ProgressPercent(shipment.Status)" aria-valuemin="0" aria-valuemax="100">
                    @shipment.Status
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private ShipmentDto? shipment;
    private bool searched;
    private bool searching;

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searching = true;
        shipment = await ShipmentService.GetByTrackingNumberAsync(trackingNumber.Trim());
        searchedNumber = trackingNumber.Trim();
        searched = true;
        searching = false;
    }

    private async Task OnKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await Search();
    }

    private static string StatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private static string ProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Cancelled => "bg-danger",
        ShipmentStatus.Delivered => "bg-success",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };

    private static int ProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Cancelled => 100,
        _ => 0
    };
}

